export function validateCameraTarget(v){if(!v||!Number.isInteger(v.x)||!Number.isInteger(v.y)||v.x<0||v.y<0||v.x>=48||v.y>=48||!Number.isFinite(v.zoom)||v.zoom<.4||v.zoom>2.5)throw Error('Choose map coordinates from 1 to 48 and zoom from 40% to 250%.');return{x:v.x,y:v.y,zoom:v.zoom};}
export function moveScenarioCamera(renderer,target){const v=validateCameraTarget(target);renderer.setZoom(v.zoom);const p=renderer.project(v.x,v.y);renderer.pan.x+=renderer.w/2-p.x;renderer.pan.y+=renderer.h/2-p.y-renderer.unit/2;renderer.hover=null;renderer.drag=null;renderer.goalArea=null;renderer.updateGoalAreaIndicator?.();renderer.dirty=true;}
